"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["86366"],{99193(e){e.exports=JSON.parse('{"id":"F342","slug":"swap-comparative-advantage","name":"Swap Gains from Comparative Advantage","subject":"Derivatives","section":"Derivatives","topic":"Interest rate swaps","level":"Intermediate","aliases":["quality spread differential","swap dealer","why firms use swaps"],"formula":{"latex":"\\\\text{Gain}=(r^{fix}_{B}-r^{fix}_{A})-(m^{flt}_{B}-m^{flt}_{A})","also":[],"text":"Total gain from the swap = (Fixed-rate gap between the weaker and stronger borrower) - (Floating-spread gap between them); each side saves half of what remains after the dealer\'s fee"},"symbols":[{"symbol":"r^fix_A, r^fix_B","meaning":"Fixed rates available to the stronger borrower (A) and the weaker borrower (B)","unit":"per year"},{"symbol":"m^flt_A, m^flt_B","meaning":"Spreads over the floating rate available to A and B","unit":"per year"},{"symbol":"Fee","meaning":"Dealer\'s fee for arranging the swap","unit":"per year"}],"when_to_use":"Use it to see why two firms might swap. The weaker borrower pays a much bigger penalty in the fixed market than in the floating market. The firms borrow where they have an advantage and swap, and the total saving is the gap between the two penalties.","worked_example":{"problem":"Firm A can borrow at a fixed 5.0% or at SOFR + 0.6%. Firm B can borrow at a fixed 6.2% or at SOFR + 1.4%. A dealer takes 0.1% for arranging a swap. How much does each firm save?","inputs":{"fa":5,"fb":6.2,"ma":0.6,"mb":1.4,"fee":0.1},"steps":[{"label":"Fixed-rate gap = B - A","working":"0.062-0.05","value":"1.20%"},{"label":"Floating-spread gap = B - A","working":"0.014-0.006","value":"0.80%"},{"label":"Total gain = fixed gap - floating gap","working":"0.012-0.008","value":"0.40%"},{"label":"After the dealer fee","working":"0.004-0.001","value":"0.30%"},{"label":"Saving for each firm (shared equally)","working":"0.003 / 2","value":"0.15%"}],"answer":"The fixed-rate gap is 1.20% and the floating gap is 0.80%, so the total gain is 0.40%. After the dealer\'s fee of 0.10% there is 0.30% left, so each firm saves 0.15% a year compared with borrowing directly."},"calculator":{"available":true,"inputs":[{"id":"fa","label":"Firm A fixed rate","unit":"%","type":"number","default":5,"hint":""},{"id":"fb","label":"Firm B fixed rate","unit":"%","type":"number","default":6.2,"hint":""},{"id":"ma","label":"Firm A floating spread","unit":"%","type":"number","default":0.6,"hint":""},{"id":"mb","label":"Firm B floating spread","unit":"%","type":"number","default":1.4,"hint":""},{"id":"fee","label":"Dealer fee","unit":"%","type":"number","default":0.1,"hint":""}],"checks":[],"steps":[{"id":"dfix","label":"Fixed-rate gap = B - A","expr":"fb-fa","format":"pct2"},{"id":"dflt","label":"Floating-spread gap = B - A","expr":"mb-ma","format":"pct2"},{"id":"gain","label":"Total gain = fixed gap - floating gap","expr":"dfix-dflt","format":"pct2"},{"id":"net","label":"After the dealer fee","expr":"gain-fee","format":"pct2"},{"id":"each","label":"Saving for each firm (shared equally)","expr":"net/2","format":"pct2"}],"results":["gain","each"],"percent_inputs_typed_as_whole_numbers":true,"tested_against":{"dfix":0.012,"dflt":0.008,"gain":0.004,"net":0.003,"each":0.0015}},"finder":{"finds":"How much two firms save by swapping","needs":"Fixed rates and floating spreads for two firms, dealer fee"},"related":[{"slug":"swap-fixed-rate","name":"Interest Rate Swap: Fair Fixed Rate"},{"slug":"all-in-loan-cost","name":"All-In Cost of a Loan (One Year)"}],"related_ids":["F340","F188"],"group":"Markets and instruments","mathml":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\" display=\\"block\\"><semantics><mrow><mtext>Gain</mtext><mo>=</mo><mo stretchy=\\"false\\">(</mo><msubsup><mi>r</mi><mi>B</mi><mrow><mi>f</mi><mi>i</mi><mi>x</mi></mrow></msubsup><mo>\u2212</mo><msubsup><mi>r</mi><mi>A</mi><mrow><mi>f</mi><mi>i</mi><mi>x</mi></mrow></msubsup><mo stretchy=\\"false\\">)</mo><mo>\u2212</mo><mo stretchy=\\"false\\">(</mo><msubsup><mi>m</mi><mi>B</mi><mrow><mi>f</mi><mi>l</mi><mi>t</mi></mrow></msubsup><mo>\u2212</mo><msubsup><mi>m</mi><mi>A</mi><mrow><mi>f</mi><mi>l</mi><mi>t</mi></mrow></msubsup><mo stretchy=\\"false\\">)</mo></mrow><annotation encoding=\\"application/x-tex\\">\\\\text{Gain}=(r^{fix}_{B}-r^{fix}_{A})-(m^{flt}_{B}-m^{flt}_{A})</annotation></semantics></math></span>","alsoMathml":[],"prev":{"slug":"sustainable-growth-rate","name":"Sustainable Growth Rate"},"next":{"slug":"money-market-yields","name":"T-Bill Discount Yield and Money Market Yields"},"lesson":null,"total":522}')}}]);